export class Cursor {
  constructor(s) {
    this.s = s
    this.i = 0
  }

  eof() {
    return this.i >= this.s.length
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : undefined
  }

  next() {
    return this.s[this.i++]
  }

  skipWS() {
    while (this.peek() === ' ' || this.peek() === '\t') this.i++
  }
}

