const BARE_CHAR = /[A-Za-z0-9_-]/

function readBareName(cursor) {
  const start = cursor.i
  while (!cursor.eof() && BARE_CHAR.test(cursor.peek())) cursor.i++
  if (cursor.i === start) return null
  return cursor.s.slice(start, cursor.i)
}

const HEX = /[0-9a-fA-F]/

/** Parses a basic (double-quoted) or literal (single-quoted) string starting at the cursor. */
export function parseQuotedString(cursor) {
  const quote = cursor.next()
  const basic = quote === '"'
  let out = ''
  for (;;) {
    if (cursor.eof()) throw new DocError('unterminated string')
    const c = cursor.next()
    if (c === quote) return out
    if (basic && c === '\\') {
      if (cursor.eof()) throw new DocError('unterminated string')
      const e = cursor.next()
      switch (e) {
        case '"': out += '"'; break
        case '\\': out += '\\'; break
        case 'n': out += '\n'; break
        case 't': out += '\t'; break
        case 'r': out += '\r'; break
        case '0': out += '\0'; break
        case 'u': {
          let hex = ''
          for (let k = 0; k < 4; k++) {
            if (cursor.eof() || !HEX.test(cursor.peek())) throw new DocError('invalid escape \\u')
            hex += cursor.next()
          }
          out += String.fromCharCode(parseInt(hex, 16))
          break
        }
        default:
