export function parseName(cursor) {
  const c = cursor.peek()
  if (c === '"' || c === "'") return parseQuotedString(cursor)
  const name = readBareName(cursor)
  if (name === null) throw new DocError('expected a name')
  return name
}

/** Parses a dotted name: names joined by '.', with spaces/tabs allowed around each dot. */
export function parseDottedName(cursor) {
  const names = []
  cursor.skipWS()
  names.push(parseName(cursor))
  for (;;) {
    cursor.skipWS()
    if (cursor.peek() !== '.') break
    cursor.i++
    cursor.skipWS()
    names.push(parseName(cursor))
  }
  return names
}
