/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { parseDocument } from './document.js'
import { toJSON, toKeys } from './output.js'

function fail(message, code) {
  process.stderr.write(`${message}\n`)
  process.exitCode = code
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    fail('error: usage: cli.js json|keys', 2)
    return
  }
  const mode = args[0]
  const input = await readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    fail(`error: ${e.message}`, 2)
    return
  }

  const output = mode === 'json' ? toJSON(root) : toKeys(root)
  process.stdout.write(output)
  process.exitCode = 0
}

main().catch((e) => {
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
})
"}

